import {
  Object3D,
  PlaneGeometry,
  Color,
  Vector3,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  uv,
  uniform,
  vec4,
  mix,
  abs,
  min,
  clamp,
  texture,
  float,
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { scenePosition, sceneRotation, sceneScale } = config;
  const visual = config.visual || {};
  const colors = visual.colors || {};
  const accentColor = new Color(colors.accent || '#ff2a38');

  // Load texture (cached)
  const ceramicTexture = ctx.textureLoader.load(
    '/prism-assets/chrome/ceramic-grain.map.png'
  );

  // --- Material with rim / accent edge light using TSL ---
  const focusUniform = uniform(0.0);          // 0 = off, 1 = full glow
  const edgeWidth = 0.05;                     // width in UV space
  const uvCoords = uv();
  const distX = abs(uvCoords.x - 0.5).mul(2.0);
  const distY = abs(uvCoords.y - 0.5).mul(2.0);
  const edgeDist = min(distX, distY);
  // edgeFactor = 1 at immediate border, 0 inside
  const edgeFactor = clamp(
    (edgeDist - (1.0 - edgeWidth)).div(edgeWidth),
    0.0,
    1.0
  );
  const baseColor = texture(ceramicTexture).rgb;
  const borderColor = vec4(accentColor, 1.0);
  const finalColor = mix(
    vec4(baseColor, 1.0),
    borderColor,
    edgeFactor.mul(focusUniform)
  );

  const material = new MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  // --- Geometry (capsule-like plane) ---
  const geometry = new PlaneGeometry(0.8, 0.3);

  // --- Mesh ---
  const mesh = new Object3D();
  const planeMesh = new Object3D(); // container to apply transform
  planeMesh.add(new (require('three/webgpu').Mesh)(geometry, material));
  mesh.add(planeMesh);

  // Apply scene placement
  planeMesh.position.set(
    scenePosition.x ?? 0,
    scenePosition.y ?? 1.6,
    scenePosition.z ?? 0
  );
  planeMesh.rotation.set(
    sceneRotation.x ?? 0,
    sceneRotation.y ?? 0,
    sceneRotation.z ?? 0
  );
  planeMesh.scale.set(
    sceneScale.x ?? 1,
    sceneScale.y ?? 1,
    sceneScale.z ?? 1
  );

  // --- GSAP timelines for hover lift, press-down, focus ---
  const hoverTimeline = gsap.timeline({ paused: true });
  const pressTimeline = gsap.timeline({ paused: true });
  const focusTimeline = gsap.timeline({ paused: true });

  // Hover lift (rise‑in with subtle offset 0.15)
  const initialY = planeMesh.position.y;
  hoverTimeline.to(planeMesh.position, {
    y: initialY + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Press‑down on click (scale 0.97, 120ms, back.out)
  const initialScale = planeMesh.scale.x;
  pressTimeline
    .to(planeMesh.scale, {
      x: initialScale * 0.97,
      y: initialScale * 0.97,
      z: initialScale * 0.97,
      duration: 0.12,
      ease: 'back.out',
    })
    .to(
      planeMesh.scale,
      {
        x: initialScale,
        y: initialScale,
        z: initialScale,
        duration: 0.12,
        ease: 'back.out',
      },
      '+=0.12'
    );

  // Accent edge on focus (animate focusUniform to 1)
  focusTimeline.to(
    { val: 0 },
    {
      val: 1,
      duration: 0.3,
      ease: 'power2.out',
      onUpdate: function () {
        focusUniform.value = this.targets()[0].val;
      },
    }
  );

  // --- Event handlers attached to userData ---
  mesh.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
      focusTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
      focusTimeline.reverse();
    },
    click: () => {
      // Emit 'hub-collection.select' (custom event callback)
      pressTimeline.restart();
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-collection.select', { source: 'badge' });
      } else {
        console.log('[Badge] Click emitted: hub-collection.select');
      }
    },
  };

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    hoverTimeline.kill();
    pressTimeline.kill();
    focusTimeline.kill();
    planeMesh.children.forEach((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        child.material.dispose();
      }
    });
    // texture disposal handled by context
  };

  return mesh;
}
